type InfiniteSliderProps = {
  children: ReactNode;
  gap?: number;
  speed?: number;
  speedOnHover?: number;
  className?: string;
};

function InfiniteSlider({
  children,
  gap = 112,
  speed = 40,
  speedOnHover,
  className,
}: InfiniteSliderProps) {
  const [currentSpeed, setCurrentSpeed] = useState(speed);
  const [ref, { width }] = useMeasure();
  const translation = useMotionValue(0);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [key, setKey] = useState(0);

  useEffect(() => {
    if (width === 0) return;

    const contentSize = width + gap;
    const from = 0;
    const to = -contentSize / 2;
    const distanceToTravel = Math.abs(to - from);
    const duration = distanceToTravel / currentSpeed;

    let controls: ReturnType<typeof animate>;
    if (isTransitioning) {
      const remainingDistance = Math.abs(translation.get() - to);
      const transitionDuration = remainingDistance / currentSpeed;
      controls = animate(translation, [translation.get(), to], {
        ease: "linear",
        duration: transitionDuration,
        onComplete: () => {
          setIsTransitioning(false);
          setKey((prevKey) => prevKey + 1);
        },
      });
    } else {
      controls = animate(translation, [from, to], {
        ease: "linear",
        duration,
        repeat: Infinity,
        repeatType: "loop",
        repeatDelay: 0,
        onRepeat: () => {
          translation.set(from);
        },
      });
    }

    return () => controls?.stop();
  }, [key, translation, currentSpeed, width, gap, isTransitioning]);

  const hoverProps = speedOnHover
    ? {
        onHoverStart: () => {
          setIsTransitioning(true);
          setCurrentSpeed(speedOnHover);
        },
        onHoverEnd: () => {
          setIsTransitioning(true);
          setCurrentSpeed(speed);
        },
      }
    : {};

  return (
    <div className={cn("overflow-x-hidden", className)}>
      <motion.div
        className="flex w-max items-center"
        style={{ x: translation, gap: `${gap}px` }}
        ref={ref}
        {...hoverProps}
      >
        <Fragment key="a">{children}</Fragment>
        <Fragment key="b">{children}</Fragment>
      </motion.div>
    </div>
  );
}

function BlurredInfiniteSlider({
  fadeWidth = 80,
  containerClassName,
  ...sliderProps
}: InfiniteSliderProps & { fadeWidth?: number; containerClassName?: string }) {
  const maskStyle: CSSProperties = {
    maskImage: `linear-gradient(to right, transparent, black ${fadeWidth}px, black calc(100% - ${fadeWidth}px), transparent)`,
    WebkitMaskImage: `linear-gradient(to right, transparent, black ${fadeWidth}px, black calc(100% - ${fadeWidth}px), transparent)`,
  };

  return (
    <div className={cn("relative w-full", containerClassName)} style={maskStyle}>
      <InfiniteSlider {...sliderProps} />
    </div>
  );
}

