function shuffle<T>(items: T[]): T[] {
  const result = [...items];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

function buildAlternatingOrder(entries: LogoEntry[]): LogoEntry[] {
  const colorLogos = entries.filter((entry) => entry.mode === "color");
  const monoLogos = entries.filter((entry) => entry.mode === "mono");

  for (let attempt = 0; attempt < 30; attempt++) {
    const shuffledColors = shuffle(colorLogos);
    const shuffledMonos = shuffle(monoLogos);
    const gapCount = shuffledColors.length + 1;
    const chosenGaps = new Set(
      shuffle(Array.from({ length: gapCount }, (_, i) => i)).slice(0, shuffledMonos.length),
    );

    const result: LogoEntry[] = [];
    let monoIndex = 0;
    for (let gap = 0; gap < gapCount; gap++) {
      if (chosenGaps.has(gap)) result.push(shuffledMonos[monoIndex++]);
      if (gap < shuffledColors.length) result.push(shuffledColors[gap]);
    }

    const isFirstMono = result[0]?.mode === "mono";
    const isLastMono = result[result.length - 1]?.mode === "mono";
    if (!(isFirstMono && isLastMono)) return result;
  }

  return entries;
}

function useIsDesktop() {
  const [isDesktop, setIsDesktop] = useState(true);

  useEffect(() => {
    const query = window.matchMedia("(min-width: 1024px)");
    setIsDesktop(query.matches);
    const handler = (e: MediaQueryListEvent) => setIsDesktop(e.matches);
    query.addEventListener("change", handler);
    return () => query.removeEventListener("change", handler);
  }, []);

  return isDesktop;
}

export function LogoCloud() {
  const [isMounted, setIsMounted] = useState(false);
  const [logos, setLogos] = useState<LogoEntry[]>(ALL_LOGOS);
  const isDesktop = useIsDesktop();

  useEffect(() => {
    setLogos(buildAlternatingOrder(ALL_LOGOS));
    setIsMounted(true);
  }, []);

  const displayedLogos = isMounted ? logos : ALL_LOGOS;

  return (
    <section
      data-slot="logo-cloud"
      className="mx-auto w-full max-w-[1536px] px-3 py-10 lg:px-5 lg:py-24"
    >
      <BlurredInfiniteSlider
        gap={isDesktop ? 140 : 24}
        speed={isDesktop ? 40 : 10}
        speedOnHover={isDesktop ? 20 : 5}
        fadeWidth={80}
        className="py-8"
      >
        {displayedLogos.map(({ id, Component, className }) => (
          <Component key={id} className={className} />
        ))}
      </BlurredInfiniteSlider>
    </section>
  );
}
